/**
 * @fileoverview The part of a Prisma client the adapter uses, as a structural type, and the executors that run a
 * {@link Sql} statement through it.
 * @layer prisma
 *
 * The type names only three members, so a client generated by either generator and any supported major version
 * satisfies it, and this module does not import Prisma. The statement's text and values go to the client's
 * `$queryRawUnsafe`/`$executeRawUnsafe`; see `sql.ts` for why that is safe.
 */

import type { Sql } from './sql'

/** The two raw-query methods of a Prisma client, or of the client a transaction hands to its callback. */
export interface RawExecutor {
  /** Runs a query with its values bound to `$1`, `$2`, … and resolves to the rows. */
  $queryRawUnsafe<T = unknown>(query: string, ...values: unknown[]): PromiseLike<T>
  /** Runs a statement with its values bound to `$1`, `$2`, … and resolves to the number of rows it affected. */
  $executeRawUnsafe(query: string, ...values: unknown[]): PromiseLike<number>
}

/** What the adapter needs of the host's Prisma client: the raw-query methods and an interactive transaction. */
export interface PrismaRawClient extends RawExecutor {
  /** Runs the callback in a transaction, handing it the client to use inside it. */
  $transaction<R>(fn: (tx: RawExecutor) => Promise<R>): Promise<R>
}

/** Runs {@link Sql} statements through a raw executor. */
export class SqlExecutor {
  private readonly raw: RawExecutor

  constructor(raw: RawExecutor) {
    this.raw = raw
  }

  /**
   * Runs a query.
   *
   * @param statement The statement; its values are bound as parameters.
   * @returns The rows.
   */
  async query<T = unknown>(statement: Sql): Promise<T> {
    return await this.raw.$queryRawUnsafe<T>(statement.text, ...statement.parameters)
  }

  /**
   * Runs a statement that returns no rows.
   *
   * @param statement The statement; its values are bound as parameters.
   * @returns The number of rows it affected.
   */
  async execute(statement: Sql): Promise<number> {
    return await this.raw.$executeRawUnsafe(statement.text, ...statement.parameters)
  }
}

/** A {@link SqlExecutor} over the host's client, which can also open a transaction. */
export class SqlClient extends SqlExecutor {
  private readonly client: PrismaRawClient

  constructor(client: PrismaRawClient) {
    super(client)
    this.client = client
  }

  /**
   * Runs the callback in a transaction.
   *
   * @param fn The work, given an executor that runs inside the transaction.
   * @returns What the callback resolves to.
   */
  transaction<R>(fn: (tx: SqlExecutor) => Promise<R>): Promise<R> {
    return this.client.$transaction((tx) => fn(new SqlExecutor(tx)))
  }
}
